namespace EduTrack.Models; public class GradingScaleVersion { public int Id { get; set; } public int GradingScaleId { get; set; } public GradingScale? GradingScale { get; set; } public int VersionNumber { get; set; } public bool IsPublished { get; set; } public DateTime CreatedDate { get; set; } = DateTime.UtcNow; public DateTime? PublishedDate { get; set; } public ICollection<GradingScaleBand> Bands { get; set; } = new List<GradingScaleBand>(); public bool CoversCompleteRange() { var bands=Bands.OrderBy(x=>x.MinimumScore).ToList(); if(bands.Count==0||bands[0].MinimumScore!=0||bands[^1].MaximumScore!=100)return false; for(var i=0;i<bands.Count;i++){if(bands[i].MinimumScore<0||bands[i].MaximumScore>100||bands[i].MinimumScore>bands[i].MaximumScore)return false;if(i>0&&bands[i-1].MaximumScore+1!=bands[i].MinimumScore)return false;} return true; } }
